settings.custom_liquid:
{%- assign v = product.selected_or_first_available_variant -%}
{%- if v.compare_at_price > v.price -%}
{%- assign save = v.compare_at_price | minus: v.price -%}
{%- assign pct = save | times: 100 | divided_by: v.compare_at_price -%}
<p class="nova-save">You save {{ save | money_without_trailing_zeros }} ({{ pct }}% off) · Inclusive of all taxes</p>
<style>.nova-save{margin:-.6rem 0 1.2rem;font-size:1.4rem;font-weight:600;color:#1f7a4d;letter-spacing:.02rem}</style>
{%- endif -%}

{%- if product.available -%}
<div class="nova-buybox">
  <div class="nova-buybox__row nova-only-in">
    <span class="nova-buybox__icon" aria-hidden="true">{%- render 'icon-accordion', icon: 'truck' -%}</span>
    <span><strong>Free delivery in India</strong><br><span class="nova-buybox__sub">Get it by <span class="nova-eta__date">3–7 days</span></span></span>
  </div>
  <div class="nova-buybox__row nova-only-intl">
    <span class="nova-buybox__icon" aria-hidden="true">{%- render 'icon-accordion', icon: 'plane' -%}</span>
    <span><strong>Worldwide shipping available</strong><br><span class="nova-buybox__sub">Shipping charges depend on your destination and are shown at checkout</span></span>
  </div>
  <div class="nova-buybox__row">
    <span class="nova-buybox__icon" aria-hidden="true">{%- render 'icon-accordion', icon: 'lock' -%}</span>
    <span><strong>Pay securely online</strong><br><span class="nova-buybox__sub">UPI, cards &amp; netbanking · Encrypted checkout<span class="nova-only-in"> · Cash on Delivery also available</span></span></span>
  </div>
  <div class="nova-buybox__row">
    <span class="nova-buybox__icon" aria-hidden="true">{%- render 'icon-accordion', icon: 'return' -%}</span>
    <span><strong>7-day easy replacement</strong><br><span class="nova-buybox__sub">Damaged or wrong item? We replace it or refund you</span></span>
  </div>
</div>
<style>
.nova-buybox{border:1px solid rgba(var(--color-foreground),.12);border-radius:8px;margin:.2rem 0 1.4rem}
.nova-buybox__row{display:flex;gap:1.2rem;align-items:flex-start;padding:1.1rem 1.4rem;font-size:1.45rem;line-height:1.4;color:rgb(var(--color-foreground))}
.nova-buybox__row + .nova-buybox__row{border-top:1px solid rgba(var(--color-foreground),.08)}
.nova-buybox__icon{width:2rem;flex-shrink:0;margin-top:.2rem}
.nova-buybox__sub{font-size:1.3rem;opacity:.75}
</style>
<script>
(function(){var el=document.querySelectorAll('.nova-eta__date');if(!el.length)return;function add(d,n){var x=new Date(d),c=0;while(c<n){x.setDate(x.getDate()+1);if(x.getDay()!==0)c++;}return x;}
var now=new Date(),o={weekday:'short',day:'numeric',month:'short'};var t=add(now,3).toLocaleDateString('en-IN',o)+' – '+add(now,7).toLocaleDateString('en-IN',o);
el.forEach(function(e){e.textContent=t;});})();
</script>
{%- endif -%}

{%- if product.available -%}
<div class="nova-sticky-atc" hidden>
  <div class="nova-sticky-atc__info"><span class="nova-sticky-atc__title">{{ product.title | escape }}</span><span class="nova-sticky-atc__price">{{ product.selected_or_first_available_variant.price | money }}</span></div>
  <button type="button" class="button nova-sticky-atc__btn">Add to cart</button>
</div>
<style>
.nova-sticky-atc{position:fixed;left:0;right:0;bottom:0;z-index:3;display:flex;align-items:center;gap:1.2rem;padding:1rem 1.6rem calc(1rem + env(safe-area-inset-bottom));background:rgb(var(--color-background));box-shadow:0 -4px 16px rgba(0,0,0,.08);border-top:1px solid rgba(var(--color-foreground),.1)}
.nova-sticky-atc[hidden]{display:none}
.nova-sticky-atc__info{flex:1;min-width:0;display:flex;flex-direction:column;font-size:1.3rem;line-height:1.3;color:rgb(var(--color-foreground))}
.nova-sticky-atc__title{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.nova-sticky-atc__price{font-weight:700}
.nova-sticky-atc__btn{min-width:13rem;margin:0}
@media screen and (max-width:749px){
  body.nova-sticky-on{padding-bottom:7.2rem}
  body.nova-sticky-on #ShopifyChat,body.nova-sticky-on #dummy-chat-button-iframe,body.nova-sticky-on inbox-online-store-chat{bottom:7.6rem!important}
}
@media screen and (min-width:750px){.nova-sticky-atc{display:none!important}}
</style>
<script>
(function(){var bar=document.querySelector('.nova-sticky-atc');var main=document.querySelector('product-form button[name="add"]');if(!bar||!main||!('IntersectionObserver' in window))return;
new IntersectionObserver(function(e){var show=!e[0].isIntersecting&&e[0].boundingClientRect.top<0&&!main.disabled;bar.hidden=!show;document.body.classList.toggle('nova-sticky-on',show);}).observe(main);
bar.querySelector('button').addEventListener('click',function(){main.click();});})();
</script>
{%- endif -%}
